<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>Auditing Model Substitution in LLM APIs</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500;600;700&family=Newsreader:opsz,wght@6..72,500;6..72,650;6..72,750&display=swap" rel="stylesheet">
<style>
{base}

/* === THEME VARIABLES === */
:root {{
  --bg: #08110f;
  --panel: rgba(13, 28, 25, 0.82);
  --panel-2: rgba(20, 44, 39, 0.72);
  --ink: #eef7e8;
  --muted: #aebdb3;
  --faint: #6e8278;
  --line: rgba(172, 255, 205, 0.18);
  --green: #9cffb9;
  --cyan: #71f4ff;
  --amber: #ffd166;
  --red: #ff6b6b;
  --blue: #9bbcff;
  --title-font: 'Newsreader', serif;
  --mono-font: 'IBM Plex Mono', monospace;
  --slide-padding: clamp(1.1rem, 3.2vw, 3.15rem);
  --title-size: clamp(2.05rem, 5.2vw, 4.9rem);
  --h2-size: clamp(1.55rem, 3.35vw, 3rem);
  --h3-size: clamp(0.95rem, 1.8vw, 1.45rem);
  --body-size: clamp(0.68rem, 1.08vw, 1rem);
  --small-size: clamp(0.55rem, 0.82vw, 0.78rem);
}}

/* === GLOBAL PRESENTATION BASE === */
* {{ box-sizing: border-box; }}
body {{ margin: 0; background: var(--bg); color: var(--ink); font-family: var(--mono-font); }}
.slide {{ isolation: isolate; background:
  radial-gradient(circle at 12% 18%, rgba(113,244,255,0.12), transparent 30%),
  radial-gradient(circle at 84% 22%, rgba(156,255,185,0.13), transparent 34%),
  linear-gradient(135deg, #050a09 0%, #0b1714 48%, #06100e 100%); }}
.slide::before {{ content: ""; position: absolute; inset: 0; z-index: -2; opacity: 0.32; background-image:
  linear-gradient(rgba(156,255,185,0.08) 1px, transparent 1px),
  linear-gradient(90deg, rgba(156,255,185,0.08) 1px, transparent 1px);
  background-size: clamp(28px, 4vw, 58px) clamp(28px, 4vw, 58px); mask-image: radial-gradient(circle at center, black, transparent 82%); }}
.slide::after {{ content: ""; position: absolute; inset: clamp(0.65rem, 1.2vw, 1.1rem); border: 1px solid var(--line); pointer-events: none; z-index: -1; }}
h1, h2, h3, p {{ margin: 0; }}
h1, h2 {{ font-family: var(--title-font); letter-spacing: -0.035em; line-height: 0.96; }}
h1 {{ font-size: var(--title-size); max-width: 13ch; }}
h2 {{ font-size: var(--h2-size); max-width: 19ch; }}
h3 {{ font-size: var(--h3-size); line-height: 1.18; }}
p {{ font-size: var(--body-size); line-height: 1.5; color: var(--muted); }}
.kicker {{ font-size: var(--small-size); text-transform: uppercase; letter-spacing: 0.16em; color: var(--green); font-weight: 700; }}
.accent {{ color: var(--green); }}
.cyan {{ color: var(--cyan); }}
.amber {{ color: var(--amber); }}
.red {{ color: var(--red); }}
.muted {{ color: var(--muted); }}
.tiny {{ font-size: var(--small-size); color: var(--faint); line-height: 1.35; }}
.slide-num {{ position: absolute; right: clamp(1rem, 2vw, 2rem); bottom: clamp(0.8rem, 1.5vw, 1.5rem); color: var(--faint); font-size: var(--small-size); }}

/* === ANIMATION SYSTEM === */
.reveal {{ opacity: 0; transform: translateY(18px); animation: rise 650ms cubic-bezier(.2,.7,.1,1) forwards; animation-delay: var(--d, 0ms); }}
@keyframes rise {{ to {{ opacity: 1; transform: translateY(0); }} }}
@media (prefers-reduced-motion: reduce) {{ .reveal {{ animation: none; opacity: 1; transform: none; }} html {{ scroll-behavior: auto; }} }}

/* === SHARED LAYOUTS === */
.header {{ display: flex; justify-content: space-between; align-items: flex-start; gap: var(--content-gap); margin-bottom: clamp(0.75rem, 2vh, 1.5rem); }}
.header p {{ max-width: 47ch; padding-top: clamp(0.2rem, 0.8vh, 0.8rem); }}
.two-col {{ display: grid; grid-template-columns: 0.86fr 1.14fr; gap: clamp(0.8rem, 2vw, 2rem); align-items: center; min-height: 0; }}
.panel {{ background: linear-gradient(180deg, var(--panel), rgba(5,10,9,0.72)); border: 1px solid var(--line); border-radius: clamp(0.75rem, 1.4vw, 1.35rem); box-shadow: 0 24px 80px rgba(0,0,0,0.34); }}
.stack {{ display: grid; gap: clamp(0.45rem, 1vh, 0.9rem); }}
.badge {{ display: inline-flex; width: fit-content; align-items: center; gap: 0.5ch; border: 1px solid var(--line); border-radius: 999px; padding: clamp(0.28rem, 0.7vw, 0.48rem) clamp(0.45rem, 1vw, 0.78rem); color: var(--green); font-size: var(--small-size); background: rgba(156,255,185,0.06); }}

/* === TITLE SLIDE === */
.title-grid {{ display: grid; grid-template-columns: 1.1fr 0.9fr; gap: clamp(1rem, 3vw, 3rem); align-items: center; height: 100%; }}
.title-copy {{ display: grid; gap: clamp(0.8rem, 2vh, 1.5rem); }}
.title-copy .subtitle {{ max-width: 58ch; font-size: clamp(0.9rem, 1.35vw, 1.2rem); color: var(--muted); }}
.signal-card {{ position: relative; min-height: min(62vh, 620px); padding: clamp(1rem, 2vw, 2rem); overflow: hidden; }}
.signal-card::before {{ content: ""; position: absolute; inset: 13%; border-radius: 50%; border: 1px solid rgba(113,244,255,0.24); box-shadow: 0 0 80px rgba(113,244,255,0.18); }}
.orbit {{ position: absolute; inset: 20%; border: 1px dashed rgba(156,255,185,0.28); border-radius: 50%; animation: spin 22s linear infinite; }}
.orbit:nth-child(2) {{ inset: 31%; animation-duration: 15s; border-color: rgba(255,209,102,0.25); }}
@keyframes spin {{ to {{ transform: rotate(360deg); }} }}
.vendor-node {{ position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); width: clamp(8rem, 17vw, 15rem); aspect-ratio: 1; border-radius: 50%; display: grid; place-items: center; text-align: center; background: radial-gradient(circle, rgba(156,255,185,0.22), rgba(13,28,25,0.92)); border: 1px solid rgba(156,255,185,0.32); font-size: clamp(0.75rem, 1.1vw, 1rem); }}
.chip {{ position: absolute; padding: clamp(0.35rem, 0.8vw, 0.6rem); border-radius: 0.75rem; border: 1px solid var(--line); background: rgba(5,10,9,0.72); font-size: var(--small-size); color: var(--muted); }}
.chip.a {{ top: 13%; left: 10%; }} .chip.b {{ top: 15%; right: 8%; }} .chip.c {{ bottom: 18%; left: 7%; }} .chip.d {{ bottom: 13%; right: 13%; }}

/* === THREAT DIAGRAM === */
.hypothesis {{ padding: clamp(0.8rem, 1.5vw, 1.25rem); display: grid; gap: clamp(0.5rem, 1vh, 0.8rem); }}
.hypo-row {{ display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: clamp(0.55rem, 1vw, 0.85rem); border-radius: 0.9rem; background: rgba(255,255,255,0.035); border: 1px solid rgba(255,255,255,0.07); }}
.hypo-label {{ font-weight: 700; color: var(--cyan); }}
.swap-grid {{ display: grid; grid-template-columns: repeat(2, 1fr); gap: clamp(0.55rem, 1vw, 0.9rem); }}
.swap-card {{ padding: clamp(0.75rem, 1.4vw, 1.1rem); min-height: clamp(5.2rem, 12vh, 7.6rem); }}
.swap-card p {{ font-size: var(--small-size); margin-top: 0.4rem; }}

/* === TABLE SLIDE === */
.table-wrap {{ padding: clamp(0.45rem, 0.8vw, 0.8rem); max-width: 100%; overflow: hidden; }}
table {{ width: 100%; border-collapse: collapse; font-size: clamp(0.43rem, 0.66vw, 0.68rem); line-height: 1.15; }}
th {{ color: var(--green); font-weight: 700; text-align: left; padding: clamp(0.22rem, 0.42vw, 0.4rem); border-bottom: 1px solid var(--line); }}
td {{ padding: clamp(0.2rem, 0.37vw, 0.36rem); color: var(--muted); border-bottom: 1px solid rgba(172,255,205,0.09); }}
tr.fp8 td {{ color: #dbe8dc; background: rgba(156,255,185,0.035); }}
td.model {{ color: var(--ink); font-weight: 600; width: 25%; }}
.legend-row {{ display: flex; gap: clamp(0.4rem, 1vw, 0.8rem); flex-wrap: wrap; margin-top: clamp(0.45rem, 0.9vh, 0.75rem); }}
.callout {{ padding: clamp(0.65rem, 1.2vw, 1rem); border-left: 3px solid var(--amber); background: rgba(255,209,102,0.08); border-radius: 0.8rem; }}

/* === IMAGE SLIDES === */
.figure-layout {{ display: grid; grid-template-columns: 1.25fr 0.75fr; gap: clamp(0.8rem, 2vw, 1.7rem); align-items: center; min-height: 0; }}
.figure-box {{ padding: clamp(0.45rem, 0.9vw, 0.75rem); display: grid; place-items: center; max-height: min(64vh, 690px); }}
.figure-box img {{ width: 100%; max-height: min(61vh, 660px); border-radius: 0.75rem; object-fit: contain; }}
.findings {{ display: grid; gap: clamp(0.55rem, 1vh, 0.85rem); }}
.finding {{ padding: clamp(0.65rem, 1.2vw, 1rem); border: 1px solid var(--line); border-radius: 1rem; background: rgba(255,255,255,0.035); }}
.finding p {{ font-size: var(--small-size); margin-top: 0.28rem; }}

/* === RANDOMIZATION SLIDE === */
.mix-panel {{ padding: clamp(1rem, 2vw, 1.8rem); }}
.formula {{ font-family: var(--title-font); font-size: clamp(1.3rem, 3vw, 2.7rem); color: var(--ink); text-align: center; margin-bottom: clamp(0.8rem, 2vh, 1.4rem); }}
.routing {{ display: grid; grid-template-columns: 1fr auto 1fr; gap: clamp(0.55rem, 1vw, 0.9rem); align-items: center; }}
.bucket {{ min-height: clamp(8rem, 26vh, 16rem); border-radius: 1.15rem; border: 1px solid var(--line); background: rgba(255,255,255,0.035); padding: clamp(0.7rem, 1.3vw, 1.1rem); display: flex; flex-direction: column; justify-content: space-between; }}
.arrow {{ color: var(--green); font-size: clamp(1.2rem, 3vw, 2.4rem); }}
.bar {{ height: clamp(0.5rem, 1.2vh, 0.85rem); border-radius: 999px; background: linear-gradient(90deg, var(--green) 0 88%, var(--red) 88% 100%); border: 1px solid var(--line); }}
.bar.low {{ background: linear-gradient(90deg, var(--green) 0 97%, var(--red) 97% 100%); }}

/* === MATRIX AND TEE === */
.matrix {{ display: grid; grid-template-columns: 0.8fr 1.05fr 1.05fr; border: 1px solid var(--line); border-radius: 1rem; overflow: hidden; }}
.cell {{ padding: clamp(0.55rem, 1.05vw, 0.85rem); border-right: 1px solid rgba(172,255,205,0.12); border-bottom: 1px solid rgba(172,255,205,0.12); min-height: clamp(4.2rem, 11vh, 6.3rem); }}
.cell:nth-child(3n) {{ border-right: none; }}
.cell.head {{ background: rgba(156,255,185,0.1); color: var(--green); font-weight: 700; min-height: auto; }}
.cell p {{ font-size: clamp(0.58rem, 0.88vw, 0.82rem); }}
.tee-flow {{ display: grid; grid-template-columns: repeat(4, 1fr); gap: clamp(0.45rem, 0.9vw, 0.8rem); }}
.flow-step {{ padding: clamp(0.65rem, 1.15vw, 1rem); min-height: clamp(7rem, 20vh, 12rem); position: relative; }}
.flow-step::after {{ content: "→"; position: absolute; right: -0.8rem; top: 45%; color: var(--green); font-size: clamp(1rem, 2vw, 1.8rem); }}
.flow-step:last-child::after {{ display: none; }}
.property-grid {{ display: grid; grid-template-columns: repeat(3, 1fr); gap: clamp(0.5rem, 1vw, 0.8rem); margin-top: clamp(0.7rem, 1.5vh, 1rem); }}
.property {{ padding: clamp(0.55rem, 1vw, 0.85rem); background: rgba(113,244,255,0.06); border: 1px solid rgba(113,244,255,0.2); border-radius: 0.9rem; }}

/* === TAKEAWAYS === */
.takeaway-list {{ display: grid; grid-template-columns: repeat(5, 1fr); gap: clamp(0.45rem, 0.9vw, 0.75rem); align-items: stretch; }}
.takeaway {{ padding: clamp(0.65rem, 1.1vw, 1rem); display: grid; grid-template-rows: auto auto 1fr; gap: clamp(0.3rem, 0.65vh, 0.55rem); }}
.takeaway .num {{ font-family: var(--title-font); font-size: clamp(1.45rem, 3vw, 2.4rem); color: var(--green); }}
.takeaway p {{ font-size: clamp(0.58rem, 0.88vw, 0.82rem); }}
.cta {{ margin-top: clamp(0.75rem, 2vh, 1.3rem); display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: clamp(0.65rem, 1.2vw, 1rem); border: 1px solid rgba(156,255,185,0.28); background: rgba(156,255,185,0.08); border-radius: 1rem; }}

/* === RESPONSIVE REFINEMENTS === */
@media (max-height: 700px) {{
  .figure-box img {{ max-height: min(55vh, 520px); }}
  .swap-card, .flow-step {{ min-height: auto; }}
  table {{ font-size: clamp(0.38rem, 0.58vw, 0.56rem); }}
}}
@media (max-height: 600px) {{
  .header {{ margin-bottom: 0.45rem; }}
  .title-grid, .two-col, .figure-layout {{ gap: 0.65rem; }}
  .figure-box img {{ max-height: 49vh; }}
}}
@media (max-height: 500px), (max-width: 900px) {{
  .title-grid, .two-col, .figure-layout {{ grid-template-columns: 1fr; }}
  .takeaway-list {{ grid-template-columns: repeat(5, minmax(0, 1fr)); }}
}}
</style>
</head>
<body>

<!-- === SLIDE 1: TITLE === -->
<section class="slide" id="title-slide">
  <div class="slide-content title-grid">
    <div class="title-copy">
      <div class="kicker reveal">arxiv.org/abs/2504.04715 · LLM API Integrity</div>
      <h1 class="reveal" style="--d:90ms">Are You Getting What You Pay For?</h1>
      <p class="subtitle reveal" style="--d:180ms">Auditing Model Substitution in LLM APIs: why software tests fail and hardware attestation wins.</p>
      <div class="badge reveal" style="--d:270ms">Trust gap: black-box APIs cannot prove the advertised model is served</div>
    </div>
    <div class="signal-card panel reveal" style="--d:180ms">
      <div class="orbit"></div><div class="orbit"></div>
      <div class="vendor-node">Commercial<br>LLM API<br><span class="tiny">black-box inference</span></div>
      <div class="chip a">Advertised weights</div><div class="chip b">Cheaper route</div>
      <div class="chip c">Benchmark-facing behavior</div><div class="chip d">User traffic</div>
    </div>
  </div>
  <div class="slide-num">01 / 09</div>
</section>

<!-- === SLIDE 2: SUBSTITUTION THREAT === -->
<section class="slide" id="substitution-threat">
  <div class="slide-content">
    <div class="header">
      <div><div class="kicker reveal">Threat model</div><h2 class="reveal" style="--d:80ms">The Model Substitution Problem</h2></div>
      <p class="reveal" style="--d:140ms">API providers charge for specific models, but black-box serving gives users no direct guarantee that the advertised model is actually executed.</p>
    </div>
    <div class="two-col">
      <div class="hypothesis panel reveal" style="--d:160ms">
        <div class="hypo-row"><span class="hypo-label">H₀</span><span>P<sub>actual</sub>(y|x) = P<sub>spec</sub>(y|x)</span></div>
        <div class="hypo-row"><span class="hypo-label red">H₁</span><span>P<sub>actual</sub>(y|x) ≠ P<sub>spec</sub>(y|x)</span></div>
        <p>Given API samples, the auditor must distinguish the specified model distribution from an alternative distribution.</p>
        <div class="callout"><p><span class="amber">Economic incentive:</span> reduce GPU costs while maintaining pricing.</p></div>
      </div>
      <div class="swap-grid">
        <div class="swap-card panel reveal" style="--d:220ms"><h3>Smaller model</h3><p>Example: serving an 8B model instead of a 70B model.</p></div>
        <div class="swap-card panel reveal" style="--d:280ms"><h3>Quantized variant</h3><p>FP8 or INT8 instead of original precision.</p></div>
        <div class="swap-card panel reveal" style="--d:340ms"><h3>Fine-tuned update</h3><p>A tuned or revised model behind the same API name.</p></div>
        <div class="swap-card panel reveal" style="--d:400ms"><h3>Different family</h3><p>An entirely different architecture or provider lineage.</p></div>
      </div>
    </div>
  </div>
  <div class="slide-num">02 / 09</div>
</section>

<!-- === SLIDE 3: QUANTIZATION TABLE === -->
<section class="slide" id="quantization-benchmark-drop">
  <div class="slide-content">
    <div class="header">
      <div><div class="kicker reveal">Empirical evidence</div><h2 class="reveal" style="--d:80ms">FP8 Quantization Preserves Most Accuracy</h2></div>
      <p class="reveal" style="--d:140ms">Across five model families, benchmark differences are small enough that substitution becomes hard to separate from ordinary measurement variation.</p>
    </div>
    <div class="table-wrap panel reveal" style="--d:160ms">
      <table aria-label="Original versus FP8 benchmark scores">
        <thead><tr><th>Model</th><th>MMLU</th><th>GSM8K</th><th>MATH</th><th>GPQA Diamond</th></tr></thead>
        <tbody>
          <tr><td class="model">Llama-3-8B-Instruct</td><td>62.69 ± 0.18</td><td>61.14 ± 3.47</td><td>20.65 ± 3.43</td><td>22.62 ± 0.22</td></tr>
          <tr class="fp8"><td class="model">Llama-3-8B-Instruct-FP8</td><td>62.43 ± 0.26</td><td>60.90 ± 4.10</td><td>14.91 ± 2.49</td><td>20.14 ± 0.24</td></tr>
          <tr><td class="model">Llama-3-70B-Instruct</td><td>78.05 ± 0.08</td><td>88.06 ± 1.44</td><td>35.69 ± 1.33</td><td>29.60 ± 0.51</td></tr>
          <tr class="fp8"><td class="model">Llama-3-70B-Instruct-FP8</td><td>77.88 ± 0.13</td><td>87.35 ± 1.24</td><td>35.75 ± 1.16</td><td>33.12 ± 0.30</td></tr>
          <tr><td class="model">Gemma-2-9b-it</td><td>71.86 ± 0.08</td><td>81.80 ± 1.35</td><td>33.41 ± 0.28</td><td>28.64 ± 2.97</td></tr>
          <tr class="fp8"><td class="model">Gemma-2-9b-it-FP8</td><td>71.92 ± 0.11</td><td>79.41 ± 1.14</td><td>32.53 ± 0.34</td><td>27.81 ± 3.22</td></tr>
          <tr><td class="model">Qwen2-72B-Instruct</td><td>82.18 ± 0.08</td><td>86.72 ± 1.00</td><td>37.39 ± 1.41</td><td>29.93 ± 2.71</td></tr>
          <tr class="fp8"><td class="model">Qwen2-72B-Instruct-FP8</td><td>81.98 ± 0.08</td><td>86.82 ± 0.97</td><td>37.67 ± 1.39</td><td>31.08 ± 1.96</td></tr>
          <tr><td class="model">Mistral-7B-Instruct-v0.3</td><td>59.15 ± 0.10</td><td>35.90 ± 4.54</td><td>8.94 ± 1.24</td><td>21.60 ± 0.17</td></tr>
          <tr class="fp8"><td class="model">Mistral-7B-Instruct-v0.3-FP8</td><td>58.77 ± 0.13</td><td>32.20 ± 4.02</td><td>7.68 ± 1.23</td><td>22.72 ± 0.19</td></tr>
        </tbody>
      </table>
    </div>
    <div class="legend-row reveal" style="--d:240ms">
      <span class="badge">FP8 rows shaded</span><span class="badge amber">Many drops fall within error bars</span><span class="badge cyan">MMLU and GSM8K especially subtle</span>
    </div>
  </div>
  <div class="slide-num">03 / 09</div>
</section>

<!-- === SLIDE 4: TEMPERATURE SCALING === -->
<section class="slide" id="temperature-scaling-degradation">
  <div class="slide-content">
    <div class="header">
      <div><div class="kicker reveal">Temperature scaling</div><h2 class="reveal" style="--d:80ms">Higher Temperature Amplifies Gaps but Adds Noise</h2></div>
      <p class="reveal" style="--d:140ms">Temperature experiments at 0.2, 0.5, 1.0, and 2.0 show performance degradation across models, making substitution signals less stable.</p>
    </div>
    <div class="figure-layout">
      <div class="figure-box panel reveal" style="--d:170ms"><img src="assets/figure_1.jpg" alt="Benchmark accuracy versus temperature across four tasks" /></div>
      <div class="findings">
        <div class="finding reveal" style="--d:220ms"><h3>Across-the-board degradation</h3><p>At temperature 2.0, performance degrades broadly rather than isolating a clean substitute signature.</p></div>
        <div class="finding reveal" style="--d:280ms"><h3>Noisy separability</h3><p>The original/substitute gap can narrow or become noisy as sampling temperature increases.</p></div>
        <div class="finding reveal" style="--d:340ms"><h3>Operational implication</h3><p>Auditors cannot assume benchmark accuracy is a stable fingerprint under realistic serving settings.</p></div>
      </div>
    </div>
  </div>
  <div class="slide-num">04 / 09</div>
</section>

<!-- === SLIDE 5: LOG PROB NONDETERMINISM === -->
<section class="slide" id="log-prob-nondeterminism">
  <div class="slide-content">
    <div class="header">
      <div><div class="kicker reveal">Metadata fingerprinting</div><h2 class="reveal" style="--d:80ms">Log Probability Fingerprinting Fails</h2></div>
      <p class="reveal" style="--d:140ms">The same Llama-3-8B model can emit different log probabilities across inference frameworks, versions, and GPU hardware.</p>
    </div>
    <div class="figure-layout">
      <div class="figure-box panel reveal" style="--d:170ms"><img src="assets/figure_5.jpg" alt="Log probability variation across frameworks and hardware" /></div>
      <div class="findings">
        <div class="finding reveal" style="--d:220ms"><h3>Framework drift</h3><p>Variation appears across transformers 4.40 vs 4.50 and vLLM 0.6.2 vs 0.8.2.</p></div>
        <div class="finding reveal" style="--d:280ms"><h3>Hardware drift</h3><p>A100 and H100 deployments introduce production-level differences.</p></div>
        <div class="finding reveal" style="--d:340ms"><h3>Audit failure</h3><p>An auditor cannot distinguish legitimate infrastructure variation from actual substitution.</p></div>
      </div>
    </div>
  </div>
  <div class="slide-num">05 / 09</div>
</section>

<!-- === SLIDE 6: RANDOMIZED SUBSTITUTION === -->
<section class="slide" id="randomized-substitution">
  <div class="slide-content">
    <div class="header">
      <div><div class="kicker reveal">Adversarial routing</div><h2 class="reveal" style="--d:80ms">Low-Rate Randomization Becomes Query-Prohibitive</h2></div>
      <p class="reveal" style="--d:140ms">A provider can route only a fraction of traffic to the cheaper model. As that fraction approaches zero, the mixed distribution converges toward the specified model.</p>
    </div>
    <div class="mix-panel panel reveal" style="--d:170ms">
      <div class="formula">P<sub>mix</sub> = (1 − p)P<sub>spec</sub> + pP<sub>sub</sub></div>
      <div class="routing">
        <div class="bucket"><h3>Most queries</h3><p>Served by the specified model, preserving the expected output distribution.</p><div class="bar low"></div><span class="tiny">p approaches 0</span></div>
